import{c as d,Q as e,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"core.md 下沉決議 — Fable/Opus/Sonnet/Haiku 四模型審議報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-19-core-md-four-model-sink-deliberation.md","filePath":"research/reports/2026-07-19-core-md-four-model-sink-deliberation.md","lastUpdated":1785909234000}'),a={name:"research/reports/2026-07-19-core-md-four-model-sink-deliberation.md"};function n(s,t,l,i,c,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="core-md-下沉決議-—-fable-opus-sonnet-haiku-四模型審議報告" tabindex="-1">core.md 下沉決議 — Fable/Opus/Sonnet/Haiku 四模型審議報告 <a class="header-anchor" href="#core-md-下沉決議-—-fable-opus-sonnet-haiku-四模型審議報告" aria-label="Permalink to &quot;core.md 下沉決議 — Fable/Opus/Sonnet/Haiku 四模型審議報告&quot;">​</a></h1><blockquote><p>2026-07-19 · 主席/終審：Fable（主對話）· 提案：Opus（架構視角）/ Sonnet（執行者視角）/ Haiku（最弱讀者視角）/ Fable · 互評：Opus ↔ Sonnet 交叉投票（對抗立場，先試反駁） 議題：<code>.claude/rules/core.md</code> 是否有內容可刪除、調整或下沉至其他規則檔。</p></blockquote><h2 id="_1-流程" tabindex="-1">1. 流程 <a class="header-anchor" href="#_1-流程" aria-label="Permalink to &quot;1. 流程&quot;">​</a></h2><ol><li>三 agent 各自獨立 context 讀六源 auto-load + refs + HARNESS-CORE-v4，以不同 lens 提案（架構分層／執行者常駐需求／弱讀者可讀性）；Fable 自提第四份。</li><li>Round 2：Opus 與 Sonnet 對彼此及 Haiku/Fable 提案逐項 CONFIRM/REJECT（盲於終審傾向）。</li><li>Fable 終審：計數化裁決（非平均分），落地 + 量測。</li></ol><h2 id="_2-決議總表" tabindex="-1">2. 決議總表 <a class="header-anchor" href="#_2-決議總表" aria-label="Permalink to &quot;2. 決議總表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>提案</th><th>提案者</th><th>投票</th><th>裁決</th><th>bytes</th></tr></thead><tbody><tr><td>1</td><td>Framework Integrity 整段下沉 <code>prompt-lifecycle.md</code>（path-scoped，編輯規則時載入），core.md 留 1 行指針</td><td>Opus+Sonnet+Fable</td><td>3 CONFIRM</td><td><strong>採納</strong></td><td>−700</td></tr><tr><td>2</td><td>「壓縮可翻轉決策」跨檔去重：刪 core.md 側、保 context-management 側</td><td>Opus</td><td>Sonnet CONFIRM；Fable 原主張反向、被說服</td><td><strong>採納</strong>（放在被約束操作旁 &gt; 孤懸跨切清單）</td><td>−90</td></tr><tr><td>3</td><td>儀式深度修剪：刪「六階段是思考框架非輸出格式」，保「隨風險不隨檔位」不變式 + 全構件觸發清單</td><td>Opus</td><td>Sonnet CONFIRM</td><td><strong>採納</strong>（部分：保留觸發清單）</td><td>−50</td></tr><tr><td>4</td><td>taste 有界括號縮短</td><td>Fable</td><td>Opus+Sonnet CONFIRM</td><td><strong>採納</strong></td><td>−60</td></tr><tr><td>5</td><td>「（正式 spec 走 /spec-implement）」刪除（RESOLVER 已為 canonical 路由）</td><td>Fable</td><td>Opus+Sonnet CONFIRM</td><td><strong>採納</strong></td><td>−30</td></tr><tr><td>6</td><td>context-management §監控刪 <code>/usage</code> 指令前導、保行為信號句</td><td>Sonnet</td><td>Opus CONFIRM</td><td><strong>採納</strong></td><td>−40</td></tr><tr><td>7</td><td>subagent fan-out 刪 error-handling.md 冗餘指針</td><td>Sonnet</td><td>Opus weak CONFIRM</td><td><strong>採納</strong></td><td>−35</td></tr><tr><td>8</td><td>地圖≠疆域公理修剪為 4 字 tag</td><td>Opus</td><td>Sonnet REJECT + Fable REJECT</td><td><strong>否決</strong>：主對話自發啟用 Unknowns 紀律的動機來源，非裝飾</td><td>0</td></tr><tr><td>9</td><td>下沉核心公理（判斷vs決定/雙軸/地圖≠疆域）「理論不影響行為」</td><td>Haiku</td><td>Opus+Sonnet+Fable REJECT</td><td><strong>否決</strong>（見 §3 關鍵裁決）</td><td>0</td></tr><tr><td>10</td><td>Johari 四象限下沉 research/</td><td>Haiku</td><td>2 REJECT（Sonnet 軟化為「可再壓不可移」）</td><td><strong>否決</strong>：IDENTIFY 現役決策程序，非背景理論</td><td>0</td></tr><tr><td>11</td><td>下沉 角色≠檔位單調/廣度深度/對抗立場</td><td>Haiku</td><td>2 REJECT</td><td><strong>否決</strong>：主對話即 dispatcher/judge，此為其本職規則</td><td>0</td></tr><tr><td>12</td><td>十項歧義措辭量化改寫</td><td>Haiku</td><td>2 REJECT（bytes 淨增、違「壓縮=刪除非改寫」）</td><td><strong>否決</strong>；替代路徑：清單存本報告 §4，未來 cycle 逐項評估入 <code>judgment-rubrics.md</code>（on-demand）</td><td>0</td></tr></tbody></table><p>落地量測：六源 <code>wc -c</code> <strong>18,943 → 18,237B（−706B, −3.7%）</strong>；healthcheck FAIL=0、<code>measure.sh --gate</code> PASS。</p><p><strong>Gate 衝突調整（落地時發現，決議範圍縮小）</strong>：<code>measure.sh --gate</code> 以確定性錨點驗 ① <code>wc -c</code> 量測命令必須留在 core.md（三源矛盾防線 SSoT）② <code>Token Budget（軟性參考</code> 字面錨在 context-management.md。決議 #1 與 #6 原範圍會拔除這兩個錨——依「確定性閘門不弱化」原則，量測命令留在 core.md Framework Integrity 指針行、<code>（軟性參考）</code>措辭恢復；其餘照決議下沉。此為 L3 機械 gate 壓過 L1 審議結論的正確優先序實例。</p><h2 id="_3-關鍵裁決-受眾判定-h1–h3-否決理由-具檔案價值" tabindex="-1">3. 關鍵裁決：受眾判定（H1–H3 否決理由，具檔案價值） <a class="header-anchor" href="#_3-關鍵裁決-受眾判定-h1–h3-否決理由-具檔案價值" aria-label="Permalink to &quot;3. 關鍵裁決：受眾判定（H1–H3 否決理由，具檔案價值）&quot;">​</a></h2><p>Haiku 主張下沉公理與委派規則，理由「理論不改變我的行為」。否決依據：</p><ul><li><strong>auto-load 的受眾是主對話</strong>（quality/frontier 檔位）；sub-agent <strong>不繼承</strong> auto-load，靠 Handoff Contract 取得 context。cost 檔位視角的「我用不到」不構成下沉理由——它根本讀不到這份檔。</li><li>公理（判斷vs決定/雙軸伸縮）正是主對話<strong>做委派與驗證決策</strong>的依據；Johari 是 IDENTIFY 的現役程序；對抗立場是互審的行為閘。</li><li>此裁決本身是<strong>雙軸伸縮的實證</strong>：同一份規則，弱檔讀來是「不可操作的理論」、主對話讀來是決策邏輯——程序性指導對弱檔要更具體（由 Handoff Contract 承載），不是把主對話的判斷框架刪掉。</li></ul><h2 id="_4-haiku-歧義措辭清單-保存供未來-judgment-rubrics-評估-不入-auto-load" tabindex="-1">4. Haiku 歧義措辭清單（保存供未來 judgment-rubrics 評估；不入 auto-load） <a class="header-anchor" href="#_4-haiku-歧義措辭清單-保存供未來-judgment-rubrics-評估-不入-auto-load" aria-label="Permalink to &quot;4. Haiku 歧義措辭清單（保存供未來 judgment-rubrics 評估；不入 auto-load）&quot;">​</a></h2><p>「會改變架構的題」判準、「不清楚」門檻、「廉價確定性檢查」定義、「少量機械編輯」門檻、「重要交付」列舉、「詮釋非複述」定義、「缺陷 re-handoff vs 親改」界線、「順手修」界線、<code>/rewind</code> 可用性 fallback、N commit 查點指針化。逐項評估原則：量化若增 auto-load bytes 即下沉 refs；已有 profile/rubric 承載者改指針。</p><h2 id="_5-觀察-方法論" tabindex="-1">5. 觀察（方法論） <a class="header-anchor" href="#_5-觀察-方法論" aria-label="Permalink to &quot;5. 觀察（方法論）&quot;">​</a></h2><ul><li>三 lens 分工有效：Opus 找到分層違規（Framework Integrity 自我宣告「非執行面」卻常駐）；Sonnet 提供「常駐 vs 按需」的執行者實感並成為 H 系列最強反方；Haiku 的誤讀本身即資料（歧義清單 + 受眾判定實證）。</li><li>對抗互評改變了終審立場一次（#2 方向）——同 context 自審不會發生這件事。</li><li>TEST/APPLY 閘門區四方零提案觸碰，與「驗證閘門只加嚴不放鬆」一致。</li></ul>',15)])])}const m=d(a,[["render",n]]);export{g as __pageData,m as default};
